 * Snapshots are persisted to a JSON file inside .pi/ so they survive session
 * reload, restart, and even switching to a different session for the same
 * project.
 *
 * Commands:
 *   /undo [n]  - Revert the last n file changes (default 1)
 *   /redo [n]  - Re-apply the last n undone changes (default 1)
 *   /undo-log  - Show the undo history with current position
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { matchesKey, Text, truncateToWidth } from "@earendil-works/pi-tui";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { existsSync } from "node:fs";
import { createHash } from "node:crypto";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface FileSnapshot {
	/** Absolute path of the file */
	path: string;
	/** File content before the change (null if file did not exist) */
	before: string | null;
	/** File content after the change (null if file was deleted) */
	after: string | null;
}

interface UndoEntry {
	/** Unique id for this entry */
	id: string;
	/** Tool that made the change */
	tool: string;
	/** Human-readable description */
	description: string;
	/** Timestamp */
	timestamp: number;
	/** File snapshots */
	snapshots: FileSnapshot[];
}

interface UndoState {
	/** Ordered list of undo entries */
	entries: UndoEntry[];
	/** Current position: entries[0..position-1] are "done", entries[position..] are "undone" */
	position: number;
}

// ---------------------------------------------------------------------------
// Persistent storage
// ---------------------------------------------------------------------------

const STATE_DIR = ".pi";
const STATE_FILE = "undo-history.json";

function statePath(cwd: string): string {
	return join(cwd, STATE_DIR, STATE_FILE);
}

async function loadState(cwd: string): Promise<UndoState> {
	const filePath = statePath(cwd);
	try {
		const raw = await readFile(filePath, "utf-8");
		const parsed = JSON.parse(raw);
		if (parsed && Array.isArray(parsed.entries) && typeof parsed.position === "number") {
			return parsed as UndoState;
		}
	} catch {
		// File doesn't exist or is corrupt — start fresh
	}
	return { entries: [], position: 0 };
}

async function saveState(cwd: string, state: UndoState): Promise<void> {
	const filePath = statePath(cwd);
	await mkdir(dirname(filePath), { recursive: true });
	await writeFile(filePath, JSON.stringify(state, null, 2), "utf-8");
}

// ---------------------------------------------------------------------------
// File snapshot helpers
// ---------------------------------------------------------------------------

async function readFileOrNull(absPath: string): Promise<string | null> {
	try {
		return await readFile(absPath, "utf-8");
	} catch {
		return null;
	}
}

async function writeFileFromSnapshot(absPath: string, content: string | null): Promise<void> {
	if (content === null) {
		// File didn't exist before — delete it
		try {
			const { unlink } = await import("node:fs/promises");
			await unlink(absPath);
		} catch {
			// Already gone, fine
		}
	} else {
		await mkdir(dirname(absPath), { recursive: true });
		await writeFile(absPath, content, "utf-8");
	}
}

function shortId(): string {
	return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
}

function absPath(cwd: string, p: string): string {
	return resolve(cwd, p);
}

// ---------------------------------------------------------------------------
// Stateful extension
// ---------------------------------------------------------------------------

export default function (pi: ExtensionAPI) {
	let cwd = "";
	let state: UndoState = { entries: [], position: 0 };
	let pendingSnapshots: Map<string, string | null> = new Map(); // absPath -> before content
	let pendingDescription = "";
	let pendingTool = "";

	// ------- State reconstruction -------

	async function reloadState(ctxCwd: string): Promise<void> {
		cwd = ctxCwd;
		state = await loadState(cwd);
	}

	// ------- Capture before-state on tool_call -------

	pi.on("tool_call", async (event, ctx) => {
		const tool = event.toolName;

		if (tool === "write") {
			const input = event.input as { path?: string; content?: string };
			if (!input.path) return;
			const ap = absPath(ctx.cwd, input.path);
			const before = await readFileOrNull(ap);
			pendingSnapshots.set(ap, before);
			pendingTool = "write";
			pendingDescription = input.path;
		}

		if (tool === "edit") {
			const input = event.input as {
				path?: string;
				edits?: Array<{ oldText: string; newText: string }>;
			};
			if (!input.path) return;
			const ap = absPath(ctx.cwd, input.path);
			if (!pendingSnapshots.has(ap)) {
				const before = await readFileOrNull(ap);
				pendingSnapshots.set(ap, before);
			}
			pendingTool = "edit";
			pendingDescription = input.path;
		}

		if (tool === "bash") {
			const input = event.input as { command?: string };
			if (!input.command) return;
			const cmd = input.command.trim();

			// Detect common file-mutating patterns
			const mutatingPatterns =
				/\b(sed|awk|perl|python|node|ruby)\b.*(-i|--in-place)\b|\btee\b|\b(dd)\b|\b(>|>>)\s*\S|\bmv\b|\bcp\b|\btruncate\b|\binstall\b|\bpatch\b/i;
			if (!mutatingPatterns.test(cmd)) return;

			// Heuristic: snapshot files that appear in the command
			// This is best-effort — we grab the CWD snapshot for known file arguments
			// For a more thorough approach we'd need to parse the command
			pendingTool = "bash";
			pendingDescription = cmd.length > 120 ? cmd.slice(0, 120) + "..." : cmd;

			// For bash commands we capture the before state lazily via tool_result
			// by comparing what changed. For now, we mark that a bash mutation is pending.
			pendingSnapshots.set("__bash__", cmd);
		}
	});

	// ------- Capture after-state on tool_result -------

	pi.on("tool_result", async (event, ctx) => {
		const tool = event.toolName;

		if (tool !== "write" && tool !== "edit" && tool !== "bash") return;
		if (event.isError) {
			// Tool failed — discard pending snapshots
			pendingSnapshots.clear();
			pendingTool = "";
			pendingDescription = "";
			return;
		}

		if (pendingSnapshots.size === 0) return;

		const snapshots: FileSnapshot[] = [];

		if (tool === "bash") {
			// For bash, we captured the command but not specific files.
			// We skip detailed snapshotting for bash mutations since
			// we can't reliably determine which files changed.
			// The main value is for write and edit tools.
			pendingSnapshots.clear();
			pendingTool = "";
			pendingDescription = "";
			return;
		}

		// write or edit tool — we have before states
		for (const [ap, before] of pendingSnapshots) {
			const after = await readFileOrNull(ap);
			snapshots.push({ path: ap, before, after });
		}

		// Filter out no-op snapshots (before === after)
		const realSnapshots = snapshots.filter(
			(s) => s.before !== s.after,
		);

		if (realSnapshots.length > 0) {
			// If we've undone some entries and then make a new change,
			// discard the redo history (standard undo/redo semantics)
			if (state.position < state.entries.length) {
				state.entries = state.entries.slice(0, state.position);
			}

			state.entries.push({
				id: shortId(),
				tool: pendingTool,
				description: pendingDescription,
				timestamp: Date.now(),
				snapshots: realSnapshots,
			});
			state.position = state.entries.length;

			await saveState(cwd, state);
		}

		pendingSnapshots.clear();
		pendingTool = "";
		pendingDescription = "";
	});

	// ------- Session lifecycle -------

	pi.on("session_start", async (_event, ctx) => {
		await reloadState(ctx.cwd);
	});

	pi.on("session_shutdown", async () => {
		// Persist on shutdown (redundant but safe)
		if (cwd) {
			await saveState(cwd, state).catch(() => {});
		}
	});

	// ------- Undo command -------

	pi.registerCommand("undo", {
		description: "Undo the last file change(s). Usage: /undo [n]",
		handler: async (args, ctx) => {
			if (state.position === 0) {
				ctx.ui.notify("Nothing to undo", "warning");
				return;
			}

			const count = Math.max(1, parseInt(args?.trim() || "1", 10) || 1);
			const actualCount = Math.min(count, state.position);
			const undoEntries = state.entries.slice(state.position - actualCount, state.position);

			// Apply snapshots in reverse order (latest first)
			for (let i = undoEntries.length - 1; i >= 0; i--) {
				const entry = undoEntries[i];
				for (const snap of entry.snapshots) {
					await writeFileFromSnapshot(snap.path, snap.before);
				}
			}

			state.position -= actualCount;
			await saveState(cwd, state);

			const undone = undoEntries.map((e) => {
				const files = e.snapshots.map((s) => {
					const short = s.path.startsWith(cwd) ? s.path.slice(cwd.length + 1) : s.path;
					return short;
				});
				return `${e.tool}: ${files.join(", ")}`;
			});

			ctx.ui.notify(`Undid ${actualCount} change(s):\n${undone.map((u) => `  - ${u}`).join("\n")}`, "info");
		},
	});

	// ------- Redo command -------

	pi.registerCommand("redo", {
		description: "Redo the last undone file change(s). Usage: /redo [n]",
		handler: async (args, ctx) => {
			if (state.position >= state.entries.length) {
				ctx.ui.notify("Nothing to redo", "warning");
				return;
			}

			const count = Math.max(1, parseInt(args?.trim() || "1", 10) || 1);
			const remaining = state.entries.length - state.position;
			const actualCount = Math.min(count, remaining);
			const redoEntries = state.entries.slice(state.position, state.position + actualCount);

			// Apply snapshots forward
			for (const entry of redoEntries) {
				for (const snap of entry.snapshots) {
					await writeFileFromSnapshot(snap.path, snap.after);
				}
			}

			state.position += actualCount;
			await saveState(cwd, state);

			const redone = redoEntries.map((e) => {
				const files = e.snapshots.map((s) => {
					const short = s.path.startsWith(cwd) ? s.path.slice(cwd.length + 1) : s.path;
					return short;
				});
				return `${e.tool}: ${files.join(", ")}`;
			});

			ctx.ui.notify(`Redid ${actualCount} change(s):\n${redone.map((u) => `  - ${u}`).join("\n")}`, "info");
		},
	});

	// ------- Undo log command -------

	pi.registerCommand("undo-log", {
		description: "Show the undo/redo history",
		handler: async (_args, ctx) => {
			if (!ctx.hasUI) {
				// Print mode: just dump to notification
				const lines = formatLog(state, cwd);
				ctx.ui.notify(lines.join("\n"), "info");
				return;
			}

			await ctx.ui.custom<void>((_tui, theme, _kb, done) => {
				const lines = formatLog(state, cwd);

				const component = {
					handleInput(data: string): void {
						if (matchesKey(data, "escape") || matchesKey(data, "ctrl+c")) {
							done();
						}
					},
					render(width: number): string[] {
						const header = theme.fg("accent", theme.bold(" Undo History "));
						const border = theme.fg("borderMuted", "─");
						const rule = border.repeat(3) + header + border.repeat(Math.max(0, width - 20));

						const result: string[] = ["", truncateToWidth(rule, width), ""];

						if (lines.length === 0) {
							result.push(
								truncateToWidth(`  ${theme.fg("dim", "No file changes recorded yet.")}`, width),
							);
						} else {
							for (const line of lines) {
								if (line.isCurrent) {
									result.push(
										truncateToWidth(
											`  ${theme.fg("warning", ">>> " + line.text)}`,
											width,
										),
									);
								} else if (line.isUndone) {
									result.push(
										truncateToWidth(
											`  ${theme.fg("dim", "    " + line.text)}`,
											width,
										),
									);
								} else {
									result.push(
										truncateToWidth(
											`  ${theme.fg("muted", "    " + line.text)}`,
											width,
										),
									);
								}
							}
						}

						result.push("");
						result.push(
							truncateToWidth(
								`  ${theme.fg("dim", "Press Escape to close")}`,
								width,
							),
						);
						result.push("");

						return result;
					},
					invalidate(): void {},
				};

				return component;
			});
		},
	});
}

// ---------------------------------------------------------------------------
// Log formatting helpers
// ---------------------------------------------------------------------------

interface LogLine {
	text: string;
	isCurrent: boolean;
	isUndone: boolean;
}

function formatLog(state: UndoState, cwd: string): LogLine[] {
	const lines: LogLine[] = [];

	for (let i = state.entries.length - 1; i >= 0; i--) {
		const entry = state.entries[i];
		const isApplied = i < state.position;
		const isCurrent = i === state.position - 1;
		const isUndone = !isApplied;

		const files = entry.snapshots
			.map((s) => {
				const short = s.path.startsWith(cwd) ? s.path.slice(cwd.length + 1) : s.path;
				const created = s.before === null ? " (created)" : "";
				const deleted = s.after === null ? " (deleted)" : "";
				return short + created + deleted;
			})
			.join(", ");

		const time = new Date(entry.timestamp).toLocaleTimeString();
		const text = `[${entry.id}] ${entry.tool} ${files} (${time})`;

		lines.push({ text, isCurrent, isUndone });
	}

	return lines;
}

