  await toolCallHandler({ toolName: 'write', input: { path: 'hello.txt', content: 'should not persist' } }, mockCtx);
  fs.writeFileSync(cwd + '/hello.txt', 'should not persist');
  await toolResultHandler({ toolName: 'write', isError: true }, mockCtx);
  console.log('After failed write (should be same):', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // New file creation then undo (file should be deleted)
  await toolCallHandler({ toolName: 'write', input: { path: 'brand-new.txt', content: 'new file' } }, mockCtx);
  fs.writeFileSync(cwd + '/brand-new.txt', 'new file');
  await toolResultHandler({ toolName: 'write', isError: false }, mockCtx);
  console.log('Brand new exists:', fs.existsSync(cwd + '/brand-new.txt'));

  await undoHandler.handler('', mockCtx);
  console.log('After undo create, exists:', fs.existsSync(cwd + '/brand-new.txt'));

  await shutdownHandler({ reason: 'quit' }, mockCtx);
  try { fs.unlinkSync(dbPath); } catch {}

  console.log('\\nAll e2e tests passed!');
})();
