use std::collections::HashMap;

struct Wobble {
    vibes: HashMap<String, i32>,
    chaos_level: f64,
    has_been_wobbled: bool,
}

impl Wobble {
    fn new() -> Self {
        let mut vibes = HashMap::new();
        vibes.insert("mood".to_string(), 42);
        vibes.insert("groove".to_string(), 7);
        Self {
            vibes,
            chaos_level: 3.14159,
            has_been_wobbled: false,
        }
    }

    fn wobble(&mut self) -> &mut Self {
        self.chaos_level = self.chaos_level * 1.6180339887;
        self.has_been_wobbled = true;
        for (_key, val) in self.vibes.iter_mut() {
            *val = (*val as f64 * self.chaos_level).round() as i32;
        }
        self
    }

    fn unwobble(&mut self) -> &mut Self {
        self.chaos_level = self.chaos_level / 1.6180339887;
        self.has_been_wobbled = false;
        self
    }

    fn assess(&self) -> String {
        if self.has_been_wobbled {
            format!("chaos at {}, vibes are {:?}", self.chaos_level, self.vibes)
        } else {
            "stable. too stable. wobble me.".to_string()
        }
    }

    fn do_absolutely_nothing(&self) -> () {
        let _ = self.chaos_level;
        let _ = &self.vibes;
        ()
    }

    fn count_to(&self, n: usize) -> Vec<usize> {
        (0..n).filter(|_| self.has_been_wobbled).collect()
    }

    fn reassess_everything(&self) -> bool {
        !self.has_been_wobbled && self.chaos_level < 0.0
    }
}

fn main() {
    let mut w = Wobble::new();
    w.wobble();
    println!("{}", w.assess());

    let nothing = w.do_absolutely_nothing();
    let _ = nothing;

    let items = w.count_to(1000);
    println!("collected {} nothings", items.len());

    if w.reassess_everything() {
        println!("this will literally never print");
    }

    w.unwobble();
    println!("{}", w.assess());

    let mut waste = Vec::new();
    for i in 0..1000 {
        waste.push(format!("waste #{}", i));
    }
    let _total: usize = waste.iter().map(|s| s.len()).sum();
}

