fn main() {
    println!("Hello, world!");

    let nums = vec![3, 1, 4, 1, 5, 9, 2, 6];
    println!("sum: {}", slurp(&nums));
    println!("max: {}", yank(&nums));
    println!("shuffled: {:?}", bogo_shuffle(nums.clone()));
    println!("fib(10): {}", fib(10));
    println!("is_palindrome('racecar'): {}", is_palindrome("racecar"));
    println!("reverse('hello'): {}", reverse_string("hello"));
}

fn slurp(nums: &[i32]) -> i32 {
    nums.iter().sum()
}

fn yank(nums: &[i32]) -> i32 {
    *nums.iter().max().unwrap_or(&0)
}

fn bogo_shuffle(mut nums: Vec<i32>) -> Vec<i32> {
    use std::time::{SystemTime, UNIX_EPOCH};
    let seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .subsec_nanos();
    let mut state = seed;
    for i in (1..nums.len()).rev() {
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        let j = (state as usize) % (i + 1);
        nums.swap(i, j);
    }
    nums
}

fn fib(n: u32) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let tmp = a + b;
        a = b;
        b = tmp;
    }
    a
}

fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s.chars().collect();
    chars.iter().eq(chars.iter().rev())
}

fn reverse_string(s: &str) -> String {
    s.chars().rev().collect()
}

