import random
import hashlib
from datetime import datetime


def spin_wheel(items):
    """Picks a random item. Completely pointless."""
    return random.choice(items)


def hash_my_thoughts(thought: str) -> str:
    """Hashes a string because why not."""
    return hashlib.sha256(thought.encode()).hexdigest()[:16]


class Blob:
    def __init__(self, name, size):
        self.name = name
        self.size = size
        self.created_at = datetime.now()
        self.digest = hash_my_thoughts(name)

    def __repr__(self):
        return f"Blob({self.name!r}, {self.size}b)"

    def inflate(self, amount):
        self.size += amount
        self.digest = hash_my_thoughts(f"{self.name}:{self.size}")

    def deflate(self):
        if self.size > 0:
            self.size = max(0, self.size // 2)
        self.digest = hash_my_thoughts(f"{self.name}:{self.size}")

    def describe(self):
        return f"{self.name} is {self.size} bytes wide, born {self.created_at:%H:%M:%S}"


def main():
    blobs = [
        Blob("alpha", 1024),
        Blob("beta", 2048),
        Blob("gamma", 512),
    ]

    for b in blobs:
        b.inflate(random.randint(100, 999))
        print(b.describe())

    print(f"\nwheel of fate: {spin_wheel(['yes', 'no', 'maybe', 'ask again'])}")
    print(f"thought hash: {hash_my_thoughts('what is even happening')}")

    for b in blobs:
        b.deflate()
        print(b.describe())


if __name__ == "__main__":
    main()

