def flip_coin(n=1):
    """Flips n coins. Returns list of 'heads'/'tails'."""
    return [random.choice(["heads", "tails"]) for _ in range(n)]


def scramble(text):
    """Shuffles characters. Barely readable now."""
    chars = list(text)
    random.shuffle(chars)
    return "".join(chars)


def fibonacci_up_to(n):
    """Returns fibonacci numbers up to n. For no reason."""
    fibs = [0, 1]
    while fibs[-1] + fibs[-2] < n:
        fibs.append(fibs[-1] + fibs[-2])
    return fibs


class Sandwich:
    def __init__(self, *layers):
        self.layers = list(layers)
        self.bitten = False

    def bite(self):
        self.bitten = True
        if self.layers:
            self.layers.pop()
        return self

    def add(self, item):
        self.layers.append(item)
        return self

    def __repr__(self):
        status = "(bitten)" if self.bitten else "(intact)"
        return f"Sandwich{status}: {' | '.join(self.layers) or 'empty'}"


def main():
    blobs = [
        Blob("alpha", 1024),
        Blob("beta", 2048),
        Blob("gamma", 512),
    ]

    for b in blobs:
        b.inflate(random.randint(100, 999))
        print(b.describe())

    print(f"\nwheel of fate: {spin_wheel(['yes', 'no', 'maybe', 'ask again'])}")
    print(f"thought hash: {hash_my_thoughts('what is even happening')}")

    for b in blobs:
        b.deflate()
        print(b.describe())

    print(f"\ncoin flips: {flip_coin(5)}")
    print(f"scrambled: {scramble('hello world')}")
    print(f"fibonacci up to 100: {fibonacci_up_to(100)}")

    s = Sandwich("bread", "cheese", "lettuce", "tomato", "bread")
    print(f"\n{s}")
    s.bite().bite().add("pickles").bite()
    print(s)


if __name__ == "__main__":
