/**
 * Undo/Redo Extension
 *
 * Tracks file changes made by the agent (write and edit tools) and lets the
 * user undo, redo, or jump to any point in history. Snapshots are persisted
 * to a SQLite database inside .pi/ so they survive session reload, restart,
 * and switching sessions.
 *
 * Commands:
 *   /undo [n]     - Revert the last n file changes (default 1)
 *   /redo [n]     - Re-apply the last n undone changes (default 1)
 *   /undo-log     - Interactive timeline — navigate with arrows, Enter to jump
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Key, matchesKey, truncateToWidth } from "@earendil-works/pi-tui";
import { DatabaseSync } from "node:sqlite";
import { readFile, writeFile, mkdir, unlink } from "node:fs/promises";
import { existsSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface FileSnapshot {
	path: string;
	before: string | null;
	after: string | null;
}

interface UndoEntry {
	id: number;
	tool: string;
	description: string;
	timestamp: number;
	snapshots: FileSnapshot[];
}

// ---------------------------------------------------------------------------
// SQLite-backed undo store
// ---------------------------------------------------------------------------

class UndoStore {
	private db: DatabaseSync;

	constructor(dbPath: string) {
		const dir = dirname(dbPath);
		if (!existsSync(dir)) {
			mkdirSync(dir, { recursive: true });
		}

		this.db = new DatabaseSync(dbPath);
		this.db.exec("PRAGMA journal_mode = WAL");
		this.db.exec("PRAGMA synchronous = NORMAL");

		this.db.exec(`
			CREATE TABLE IF NOT EXISTS entries (
				id        INTEGER PRIMARY KEY AUTOINCREMENT,
				tool      TEXT NOT NULL,
				desc      TEXT NOT NULL,
				timestamp INTEGER NOT NULL
			);
			CREATE TABLE IF NOT EXISTS snapshots (
				entry_id      INTEGER NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
				path          TEXT NOT NULL,
				before_content TEXT,
				after_content  TEXT
			);
		`);

		this.stmtInsertEntry = this.db.prepare(
			"INSERT INTO entries (tool, desc, timestamp) VALUES (?, ?, ?)",
		);
		this.stmtInsertSnapshot = this.db.prepare(
			"INSERT INTO snapshots (entry_id, path, before_content, after_content) VALUES (?, ?, ?, ?)",
		);
		this.stmtLatestPosition = this.db.prepare(
			"SELECT COALESCE(MAX(id), 0) AS pos FROM entries",
		);
		this.stmtEntriesRange = this.db.prepare(
			"SELECT id, tool, desc, timestamp FROM entries WHERE id > ? AND id <= ? ORDER BY id",
		);
		this.stmtSnapshotsForEntry = this.db.prepare(
			"SELECT path, before_content, after_content FROM snapshots WHERE entry_id = ?",
		);
		this.stmtEntriesAfter = this.db.prepare(
			"SELECT id FROM entries WHERE id > ? ORDER BY id",
		);
		this.stmtAllEntries = this.db.prepare(
			"SELECT id, tool, desc, timestamp FROM entries ORDER BY id",
		);
		this.stmtDeleteAfter = this.db.prepare(
			"DELETE FROM entries WHERE id > ?",
		);
	}

	private stmtInsertEntry: ReturnType<DatabaseSync["prepare"]>;
	private stmtInsertSnapshot: ReturnType<DatabaseSync["prepare"]>;
	private stmtLatestPosition: ReturnType<DatabaseSync["prepare"]>;
	private stmtEntriesRange: ReturnType<DatabaseSync["prepare"]>;
	private stmtSnapshotsForEntry: ReturnType<DatabaseSync["prepare"]>;
	private stmtEntriesAfter: ReturnType<DatabaseSync["prepare"]>;
	private stmtAllEntries: ReturnType<DatabaseSync["prepare"]>;
	private stmtDeleteAfter: ReturnType<DatabaseSync["prepare"]>;

	getPosition(): number {
		const row = this.stmtLatestPosition.get() as { pos: number } | null;
		return row?.pos ?? 0;
	}

	addEntry(tool: string, description: string, snapshots: FileSnapshot[]): number {
		const now = Date.now();
		const info = this.stmtInsertEntry.run(tool, description, now);
		const entryId = Number(info.lastInsertRowid);

		for (const snap of snapshots) {
			this.stmtInsertSnapshot.run(entryId, snap.path, snap.before, snap.after);
		}

		return entryId;
	}

	getEntriesRange(fromId: number, toId: number): UndoEntry[] {
		const rows = this.stmtEntriesRange.all(fromId, toId) as Array<{
			id: number;
			tool: string;
			desc: string;
			timestamp: number;
		}>;
		return rows.map((r) => ({
			id: r.id,
			tool: r.tool,
			description: r.desc,
			timestamp: r.timestamp,
			snapshots: this.getSnapshots(r.id),
		}));
	}

	getSnapshots(entryId: number): FileSnapshot[] {
		const rows = this.stmtSnapshotsForEntry.all(entryId) as Array<{
			path: string;
			before_content: string | null;
			after_content: string | null;
		}>;
		return rows.map((r) => ({
			path: r.path,
			before: r.before_content,
			after: r.after_content,
		}));
	}

	getEntryIdsAfter(afterId: number): number[] {
		const rows = this.stmtEntriesAfter.all(afterId) as Array<{ id: number }>;
		return rows.map((r) => r.id);
	}

	deleteAfter(afterId: number): void {
		this.stmtDeleteAfter.run(afterId);
	}

	/** All entries in chronological order with snapshots. */
	getAllEntries(): UndoEntry[] {
		const rows = this.stmtAllEntries.all() as Array<{
			id: number;
			tool: string;
			desc: string;
			timestamp: number;
		}>;
		return rows.map((r) => ({
			id: r.id,
			tool: r.tool,
			description: r.desc,
			timestamp: r.timestamp,
			snapshots: this.getSnapshots(r.id),
		}));
	}

	close(): void {
		this.db.close();
	}
}

// ---------------------------------------------------------------------------
// File helpers
// ---------------------------------------------------------------------------

async function readFileOrNull(absPath: string): Promise<string | null> {
	try {
		return await readFile(absPath, "utf-8");
	} catch {
		return null;
	}
}

async function writeFileFromSnapshot(absPath: string, content: string | null): Promise<void> {
	if (content === null) {
		try {
			await unlink(absPath);
		} catch {
			// Already gone
		}
	} else {
		await mkdir(dirname(absPath), { recursive: true });
		await writeFile(absPath, content, "utf-8");
	}
}

function resolveAbs(cwd: string, p: string): string {
	return resolve(cwd, p);
}

function shortPath(absPath: string, cwd: string): string {
	return absPath.startsWith(cwd + "/") ? absPath.slice(cwd.length + 1) : absPath;
}

// ---------------------------------------------------------------------------
// Interactive timeline component
// ---------------------------------------------------------------------------

interface TimelineEntry {
	entry: UndoEntry;
	isApplied: boolean;
	isCurrent: boolean;
}

class TimelineComponent {
	private entries: TimelineEntry[];
	private cursorIdx: number;
	private scrollOffset: number;
	private onClose: (targetId: number | null) => void;
	private cwd: string;
	private theme: ReturnType<typeof import("@earendil-works/pi-tui")> extends never
		? never
		: { fg: (color: string, text: string) => string; bold: (text: string) => string };

	constructor(
		entries: TimelineEntry[],
		initialCursorIdx: number,
		cwd: string,
		theme: { fg: (color: string, text: string) => string; bold: (text: string) => string },
		onClose: (targetId: number | null) => void,
	) {
		this.entries = entries;
		this.cursorIdx = initialCursorIdx;
		this.scrollOffset = 0;
		this.cwd = cwd;
		this.theme = theme;
		this.onClose = onClose;
	}

	handleInput(data: string): void {
		if (matchesKey(data, Key.up) || matchesKey(data, "k")) {
			if (this.cursorIdx > 0) this.cursorIdx--;
		} else if (matchesKey(data, Key.down) || matchesKey(data, "j")) {
			if (this.cursorIdx < this.entries.length - 1) this.cursorIdx++;
		} else if (matchesKey(data, Key.pageUp)) {
			this.cursorIdx = Math.max(0, this.cursorIdx - 10);
		} else if (matchesKey(data, Key.pageDown)) {
			this.cursorIdx = Math.min(this.entries.length - 1, this.cursorIdx + 10);
		} else if (matchesKey(data, Key.home)) {
			this.cursorIdx = 0;
		} else if (matchesKey(data, Key.end)) {
			this.cursorIdx = this.entries.length - 1;
		} else if (matchesKey(data, Key.enter) || matchesKey(data, Key.return)) {
			this.onClose(this.entries[this.cursorIdx]!.entry.id);
		} else if (matchesKey(data, Key.escape) || matchesKey(data, "ctrl+c")) {
			this.onClose(null);
		}
	}

	render(width: number): string[] {
		const th = this.theme;
		const lines: string[] = [];

		// Header
		const headerText = th.fg("accent", th.bold(" File Change Timeline "));
		const border = th.fg("borderMuted", "─");
		const rule = border.repeat(3) + headerText + border.repeat(Math.max(0, width - 26));
		lines.push("");
		lines.push(truncateToWidth(rule, width));
		lines.push("");

		if (this.entries.length === 0) {
			lines.push(truncateToWidth(`  ${th.fg("dim", "No file changes recorded yet.")}`, width));
			lines.push("");
			lines.push(truncateToWidth(`  ${th.fg("dim", "Press Escape to close")}`, width));
			lines.push("");
			return lines;
		}

		// Determine visible window
		// Reserve 5 lines for header + footer hints
		const maxVisible = Math.max(3, 20);
		if (this.cursorIdx < this.scrollOffset) {
			this.scrollOffset = this.cursorIdx;
		}
		if (this.cursorIdx >= this.scrollOffset + maxVisible) {
			this.scrollOffset = this.cursorIdx - maxVisible + 1;
		}

		const visibleEntries = this.entries.slice(
			this.scrollOffset,
			this.scrollOffset + maxVisible,
		);

		// Show scroll indicator
		if (this.scrollOffset > 0) {
			lines.push(truncateToWidth(`  ${th.fg("dim", "  ↑ more above")}`, width));
		}

		for (let vi = 0; vi < visibleEntries.length; vi++) {
			const idx = this.scrollOffset + vi;
			const { entry, isApplied, isCurrent } = visibleEntries[vi]!;
			const isCursor = idx === this.cursorIdx;

			const files = entry.snapshots
				.map((s) => {
					const p = shortPath(s.path, this.cwd);
					if (s.before === null) return p + th.fg("success", "+");
					if (s.after === null) return p + th.fg("error", "x");
					return p;
				})
				.join(" ");
			const time = new Date(entry.timestamp).toLocaleTimeString();

			// Timeline rail
			let rail: string;
			if (isCurrent) {
				rail = th.fg("accent", "◀");
			} else if (isApplied) {
				rail = th.fg("success", "│");
			} else {
				rail = th.fg("dim", "╎");
			}

			// Node
			let node: string;
			if (isCurrent) {
				node = th.fg("accent", th.bold("●"));
			} else if (isApplied) {
				node = th.fg("success", "●");
			} else {
				node = th.fg("dim", "○");
			}

			// Entry line
			const tool = th.fg("toolTitle", entry.tool);
			const timeStr = th.fg("dim", time);

			let line: string;
			if (isCursor) {
				line = th.bg("selectedBg", ` ${rail} ${node} #${entry.id} ${tool} ${files} ${timeStr} `);
			} else {
				line = ` ${rail} ${node} ${th.fg("muted", `#${entry.id}`)} ${tool} ${th.fg("muted", files)} ${timeStr}`;
			}

			lines.push(truncateToWidth(line, width));
		}

		if (this.scrollOffset + maxVisible < this.entries.length) {
			lines.push(truncateToWidth(`  ${th.fg("dim", "  ↓ more below")}`, width));
		}

		// Position indicator
		const currentPos = this.entries[this.cursorIdx]!;
		const posLabel = currentPos.isApplied
			? th.fg("success", "applied")
			: th.fg("dim", "undone");
		lines.push("");
		lines.push(
			truncateToWidth(
				`  ${th.fg("muted", "Position:")} ${posLabel}  ${th.fg("dim", `#${currentPos.entry.id} / #${this.entries[this.entries.length - 1]!.entry.id}`)}`,
				width,
			),
		);

		// Keybindings
		lines.push("");
		lines.push(
			truncateToWidth(
				`  ${th.fg("dim", "↑↓ navigate")}  ${th.fg("dim", "Enter jump")}  ${th.fg("dim", "Esc cancel")}`,
				width,
			),
		);
		lines.push("");

		return lines;
	}

	invalidate(): void {}
}

// ---------------------------------------------------------------------------
// Extension
// ---------------------------------------------------------------------------

export default function (pi: ExtensionAPI) {
	let cwd = "";
	let store: UndoStore | null = null;

	let pendingSnapshots: Map<string, string | null> = new Map();
	let pendingDescription = "";
	let pendingTool = "";
	let position = 0;

	// ------- Open / close -------

	function openStore(ctxCwd: string): void {
		cwd = ctxCwd;
		const dbPath = join(ctxCwd, ".pi", "undo-history.db");
		store = new UndoStore(dbPath);
		position = store.getPosition();
	}

	function closeStore(): void {
		if (store) {
			store.close();
			store = null;
		}
	}

	// ------- Jump to a target entry id -------

	async function jumpTo(targetId: number): Promise<string | null> {
		if (!store) return null;
		if (targetId === position) return null;

		let summary: string;

		if (targetId < position) {
			// Undo: revert entries from position down to targetId
			const entries = store.getEntriesRange(targetId, position);
			for (let i = entries.length - 1; i >= 0; i--) {
				for (const snap of entries[i].snapshots) {
					await writeFileFromSnapshot(snap.path, snap.before);
				}
			}
			position = targetId;
			summary = formatEntriesSummary(entries, "Undid");
		} else {
			// Redo: apply entries from position up to targetId
			const entries = store.getEntriesRange(position, targetId);
			for (const entry of entries) {
				for (const snap of entry.snapshots) {
					await writeFileFromSnapshot(snap.path, snap.after);
				}
			}
			position = targetId;
			summary = formatEntriesSummary(entries, "Redid");
		}

		return summary;
	}

	function formatEntriesSummary(entries: UndoEntry[], verb: string): string {
		return entries
			.map((e) => {
				const files = e.snapshots.map((s) => shortPath(s.path, cwd)).join(", ");
				return `  - ${e.tool}: ${files}`;
			})
			.join("\n");
	}

	// ------- Notify model about file state changes -------

	function notifyModel(summary: string, verb: string): void {
		pi.sendMessage(
			{
				customType: "undo-redo",
				content: `${verb} ${summary}`,
				display: true,
				details: { action: verb.toLowerCase(), changes: summary },
			},
			{ deliverAs: "nextTurn" },
		);
	}

	// ------- Capture before-state on tool_call -------

	pi.on("tool_call", async (event, ctx) => {
		const tool = event.toolName;

		if (tool === "write") {
			const input = event.input as { path?: string; content?: string };
			if (!input.path) return;
			const ap = resolveAbs(ctx.cwd, input.path);
			const before = await readFileOrNull(ap);
			pendingSnapshots.set(ap, before);
			pendingTool = "write";
			pendingDescription = input.path;
		}

		if (tool === "edit") {
			const input = event.input as {
				path?: string;
				edits?: Array<{ oldText: string; newText: string }>;
			};
			if (!input.path) return;
			const ap = resolveAbs(ctx.cwd, input.path);
			if (!pendingSnapshots.has(ap)) {
				const before = await readFileOrNull(ap);
				pendingSnapshots.set(ap, before);
			}
			pendingTool = "edit";
			pendingDescription = input.path;
		}

		if (tool === "bash") {
			const input = event.input as { command?: string };
			if (!input.command) return;
			const cmd = input.command.trim();

			const mutatingPatterns =
				/\b(sed|awk|perl|python|node|ruby)\b.*(-i|--in-place)\b|\btee\b|\bdd\b|\b>[>=]?\s*\S|\b>>\s*\S|\bmv\b|\bcp\b|\btruncate\b|\binstall\b|\bpatch\b/i;
			if (!mutatingPatterns.test(cmd)) return;

			pendingTool = "bash";
			pendingDescription = cmd.length > 120 ? cmd.slice(0, 120) + "..." : cmd;
			pendingSnapshots.set("__bash__", cmd);
		}
	});

	// ------- Capture after-state on tool_result -------

	pi.on("tool_result", async (event, ctx) => {
		const tool = event.toolName;
		if (tool !== "write" && tool !== "edit" && tool !== "bash") return;
		if (event.isError) {
			pendingSnapshots.clear();
			pendingTool = "";
			pendingDescription = "";
			return;
		}
		if (pendingSnapshots.size === 0 || !store) return;

		if (tool === "bash") {
			pendingSnapshots.clear();
			pendingTool = "";
			pendingDescription = "";
			return;
		}

		const snapshots: FileSnapshot[] = [];
		for (const [ap, before] of pendingSnapshots) {
			const after = await readFileOrNull(ap);
			if (before !== after) {
				snapshots.push({ path: ap, before, after });
			}
		}

		if (snapshots.length > 0) {
			if (position < store.getPosition()) {
				store.deleteAfter(position);
			}

			const entryId = store.addEntry(pendingTool, pendingDescription, snapshots);
			position = entryId;
		}

		pendingSnapshots.clear();
		pendingTool = "";
		pendingDescription = "";
	});

	// ------- Session lifecycle -------

	pi.on("session_start", async (_event, ctx) => {
		closeStore();
		openStore(ctx.cwd);
	});

	pi.on("session_shutdown", async () => {
		closeStore();
	});

	// ------- /undo -------

	pi.registerCommand("undo", {
		description: "Undo the last file change(s). Usage: /undo [n]",
		handler: async (args, ctx) => {
			if (!store) return;

			const count = Math.max(1, parseInt(args?.trim() || "1", 10) || 1);
			const targetId = Math.max(0, position - count);

			if (targetId === position) {
				ctx.ui.notify("Nothing to undo", "warning");
				return;
			}

			const summary = await jumpTo(targetId);
			if (summary) {
				ctx.ui.notify(`Undid change(s):\n${summary}`, "info");
				notifyModel(summary, "Undid");
			}
		},
	});

	// ------- /redo -------

	pi.registerCommand("redo", {
		description: "Redo the last undone file change(s). Usage: /redo [n]",
		handler: async (args, ctx) => {
			if (!store) return;

			const count = Math.max(1, parseInt(args?.trim() || "1", 10) || 1);
			const undoneIds = store.getEntryIdsAfter(position);
			if (undoneIds.length === 0) {
				ctx.ui.notify("Nothing to redo", "warning");
				return;
			}

			const targetId = undoneIds[Math.min(count, undoneIds.length) - 1]!;
			const summary = await jumpTo(targetId);
			if (summary) {
				ctx.ui.notify(`Redid change(s):\n${summary}`, "info");
				notifyModel(summary, "Redid");
			}
		},
	});

	// ------- /undo-log (interactive timeline) -------

	pi.registerCommand("undo-log", {
		description: "Interactive file change timeline. Navigate with arrows, Enter to jump.",
		handler: async (_args, ctx) => {
			if (!store) return;

			const entries = store.getAllEntries();

			if (entries.length === 0) {
				ctx.ui.notify("No file changes recorded yet.", "info");
				return;
			}

			if (!ctx.hasUI) {
				// Non-interactive fallback
				const lines = entries.map((e) => {
					const marker = e.id <= position ? "done" : "undone";
					const files = e.snapshots.map((s) => shortPath(s.path, cwd)).join(", ");
					return `[${marker}] #${e.id} ${e.tool} ${files}`;
				});
				ctx.ui.notify(lines.join("\n"), "info");
				return;
			}

			// Build timeline entries
			const timeline: TimelineEntry[] = entries.map((e) => ({
				entry: e,
				isApplied: e.id <= position,
				isCurrent: e.id === position,
			}));

			// Start cursor on current position entry, or last entry
			const cursorStart = timeline.findIndex((t) => t.isCurrent);
			const initialCursor = cursorStart >= 0 ? cursorStart : timeline.length - 1;

			const targetId = await ctx.ui.custom<number | null>((_tui, theme, _kb, done) => {
				return new TimelineComponent(timeline, initialCursor, cwd, theme, done);
			});

			if (targetId === null || targetId === position) return;

			const summary = await jumpTo(targetId);
			if (summary) {
				const verb = targetId < position ? "Undid" : "Redid";
				ctx.ui.notify(`${verb} change(s):\n${summary}`, "info");
				notifyModel(summary, verb);
			}
		},
	});
}

arguments.content:
/**
 * Undo/Redo Extension
 *
 * Tracks file changes made by the agent (write, edit, and file-mutating bash
 * commands) and lets the user undo, redo, or jump to any point in history.
 * Snapshots are persisted to a SQLite database inside .pi/ so they survive
 * session reload, restart, and switching sessions.
 *
 * Commands:
 *   /undo [n]     - Revert the last n file changes (default 1)
 *   /redo [n]     - Re-apply the last n undone changes (default 1)
 *   /undo-log     - Interactive timeline — navigate with arrows, Enter to jump
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Key, matchesKey, truncateToWidth, type TUI } from "@earendil-works/pi-tui";
import { DatabaseSync } from "node:sqlite";
import { readFile, writeFile, mkdir, unlink, readdir, stat } from "node:fs/promises";
import { existsSync, mkdirSync } from "node:fs";
import { dirname, join, resolve, extname } from "node:path";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface FileSnapshot {
	path: string;
	before: string | null;
	after: string | null;
}

interface UndoEntry {
	id: number;
	tool: string;
	description: string;
	timestamp: number;
	snapshots: FileSnapshot[];
}

/** Pending state for an in-flight tool call, keyed by toolCallId. */
interface PendingCall {
	tool: string;
	description: string;
	/** absPath -> before content */
	beforeSnapshots: Map<string, string | null>;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum entries to keep. Oldest are pruned when exceeded. */
const MAX_ENTRIES = 500;

/** File extensions we scan for bash mtime tracking. */
const TRACKABLE_EXTENSIONS = new Set([
	".ts", ".js", ".tsx", ".jsx", ".py", ".rs", ".go", ".java", ".c", ".cpp",
	".h", ".hpp", ".rb", ".sh", ".bash", ".json", ".yaml", ".yml", ".toml",
	".md", ".txt", ".css", ".html", ".sql", ".proto", ".zig",
]);

// ---------------------------------------------------------------------------
// SQLite-backed undo store
// ---------------------------------------------------------------------------

class UndoStore {
	private db: DatabaseSync;

	constructor(dbPath: string) {
		const dir = dirname(dbPath);
		if (!existsSync(dir)) {
			mkdirSync(dir, { recursive: true });
		}

		this.db = new DatabaseSync(dbPath);
		this.db.exec("PRAGMA journal_mode = WAL");
		this.db.exec("PRAGMA synchronous = NORMAL");
		this.db.exec("PRAGMA foreign_keys = ON");

		this.db.exec(`
			CREATE TABLE IF NOT EXISTS meta (
				key   TEXT PRIMARY KEY,
				value TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS entries (
				id        INTEGER PRIMARY KEY AUTOINCREMENT,
				tool      TEXT NOT NULL,
				desc      TEXT NOT NULL,
				timestamp INTEGER NOT NULL
			);
			CREATE TABLE IF NOT EXISTS snapshots (
				entry_id       INTEGER NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
				path           TEXT NOT NULL,
				before_content TEXT,
				after_content  TEXT
			);
		`);

		this.stmtInsertEntry = this.db.prepare(
			"INSERT INTO entries (tool, desc, timestamp) VALUES (?, ?, ?)",
		);
		this.stmtInsertSnapshot = this.db.prepare(
			"INSERT INTO snapshots (entry_id, path, before_content, after_content) VALUES (?, ?, ?, ?)",
		);
		this.stmtEntriesRange = this.db.prepare(
			"SELECT id, tool, desc, timestamp FROM entries WHERE id > ? AND id <= ? ORDER BY id",
		);
		this.stmtSnapshotsForEntry = this.db.prepare(
			"SELECT path, before_content, after_content FROM snapshots WHERE entry_id = ?",
		);
		this.stmtEntriesAfter = this.db.prepare(
			"SELECT id FROM entries WHERE id > ? ORDER BY id",
		);
		this.stmtAllEntries = this.db.prepare(
			"SELECT id, tool, desc, timestamp FROM entries ORDER BY id",
		);
		this.stmtDeleteAfter = this.db.prepare(
			"DELETE FROM entries WHERE id > ?",
		);
		this.stmtCountAll = this.db.prepare(
			"SELECT COUNT(*) AS cnt FROM entries",
		);
		this.stmtMinId = this.db.prepare(
			"SELECT MIN(id) AS minId FROM entries",
		);
		this.stmtGetMeta = this.db.prepare(
			"SELECT value FROM meta WHERE key = ?",
		);
		this.stmtSetMeta = this.db.prepare(
			"INSERT OR REPLACE INTO meta (key, value) VALUES (?, ?)",
		);
	}

	private stmtInsertEntry: ReturnType<DatabaseSync["prepare"]>;
	private stmtInsertSnapshot: ReturnType<DatabaseSync["prepare"]>;
	private stmtEntriesRange: ReturnType<DatabaseSync["prepare"]>;
	private stmtSnapshotsForEntry: ReturnType<DatabaseSync["prepare"]>;
	private stmtEntriesAfter: ReturnType<DatabaseSync["prepare"]>;
	private stmtAllEntries: ReturnType<DatabaseSync["prepare"]>;
	private stmtDeleteAfter: ReturnType<DatabaseSync["prepare"]>;
	private stmtCountAll: ReturnType<DatabaseSync["prepare"]>;
	private stmtMinId: ReturnType<DatabaseSync["prepare"]>;
	private stmtGetMeta: ReturnType<DatabaseSync["prepare"]>;
	private stmtSetMeta: ReturnType<DatabaseSync["prepare"]>;

	// ---- Position persistence (fix #4) ----

	getPosition(): number {
		const row = this.stmtGetMeta.get("position") as { value: string } | null;
		return row ? parseInt(row.value, 10) || 0 : 0;
	}

	setPosition(id: number): void {
		this.stmtSetMeta.run("position", String(id));
	}

	// ---- CRUD ----

	addEntry(tool: string, description: string, snapshots: FileSnapshot[]): number {
		const now = Date.now();
		const info = this.stmtInsertEntry.run(tool, description, now);
		const entryId = Number(info.lastInsertRowid);

		for (const snap of snapshots) {
			this.stmtInsertSnapshot.run(entryId, snap.path, snap.before, snap.after);
		}

		return entryId;
	}

	getEntriesRange(fromId: number, toId: number): UndoEntry[] {
		const rows = this.stmtEntriesRange.all(fromId, toId) as Array<{
			id: number;
			tool: string;
			desc: string;
			timestamp: number;
		}>;
		return rows.map((r) => ({
			id: r.id,
			tool: r.tool,
			description: r.desc,
			timestamp: r.timestamp,
			snapshots: this.getSnapshots(r.id),
		}));
	}

	getSnapshots(entryId: number): FileSnapshot[] {
		const rows = this.stmtSnapshotsForEntry.all(entryId) as Array<{
			path: string;
			before_content: string | null;
			after_content: string | null;
		}>;
		return rows.map((r) => ({
			path: r.path,
			before: r.before_content,
			after: r.after_content,
		}));
	}

	getEntryIdsAfter(afterId: number): number[] {
		const rows = this.stmtEntriesAfter.all(afterId) as Array<{ id: number }>;
		return rows.map((r) => r.id);
	}

	deleteAfter(afterId: number): void {
		this.stmtDeleteAfter.run(afterId);
	}

	getAllEntries(): UndoEntry[] {
		const rows = this.stmtAllEntries.all() as Array<{
			id: number;
			tool: string;
			desc: string;
			timestamp: number;
		}>;
		return rows.map((r) => ({
			id: r.id,
			tool: r.tool,
			description: r.desc,
			timestamp: r.timestamp,
			snapshots: this.getSnapshots(r.id),
		}));
	}

	// ---- Cleanup (fix #5) ----

	pruneIfNeeded(): void {
		const row = this.stmtCountAll.get() as { cnt: number } | null;
		const count = row?.cnt ?? 0;
		if (count <= MAX_ENTRIES) return;

		// Keep the newest MAX_ENTRIES by deleting the oldest
		const minRow = this.stmtMinId.get() as { minId: number } | null;
		if (minRow?.minId == null) return;
		const cutoff = minRow.minId + (count - MAX_ENTRIES);
		this.db.prepare("DELETE FROM entries WHERE id < ?").run(cutoff);
		this.db.exec("VACUUM");
	}

	close(): void {
		this.db.close();
	}
}

// ---------------------------------------------------------------------------
// File helpers
// ---------------------------------------------------------------------------

async function readFileOrNull(absPath: string): Promise<string | null> {
	try {
		return await readFile(absPath, "utf-8");
	} catch {
		return null;
	}
}

async function writeFileFromSnapshot(absPath: string, content: string | null): Promise<void> {
	if (content === null) {
		try {
			await unlink(absPath);
		} catch {
			// Already gone
		}
	} else {
		await mkdir(dirname(absPath), { recursive: true });
		await writeFile(absPath, content, "utf-8");
	}
}

function resolveAbs(cwd: string, p: string): string {
	return resolve(cwd, p);
}

function shortPath(absPath: string, cwd: string): string {
	return absPath.startsWith(cwd + "/") ? absPath.slice(cwd.length + 1) : absPath;
}

/**
 * Extract likely file paths from a bash command string.
 * Covers common patterns: redirects, mv/cp/patch args, sed -i targets, etc.
 */
function extractPathsFromCommand(cmd: string): string[] {
	const paths: string[] = [];

	// Redirect targets: > file, >> file
	const redirectRe = /(?:>{1,2})\s*(\S+)/g;
	for (const m of cmd.matchAll(redirectRe)) {
		paths.push(m[1]!);
	}

	// Common commands with file operands
	// sed -i 's/...' file
	const sedRe = /\bsed\b.*?(?:-i|--in-place).*?\s+(\S+)\s*$/;
	const sedMatch = cmd.match(sedRe);
	if (sedMatch) paths.push(sedMatch[1]!);

	// mv/cp src dst
	const mvCpRe = /\b(?:mv|cp|install)\s+(?:-[a-zA-Z]+\s+)*(\S+)\s+(\S+)/;
	const mvCpMatch = cmd.match(mvCpRe);
	if (mvCpMatch) {
		paths.push(mvCpMatch[1]!);
		paths.push(mvCpMatch[2]!);
	}

	// patch < file, patch file
	const patchRe = /\bpatch\s+(?:-[a-zA-Z]+\s+)*(\S+)/;
	const patchMatch = cmd.match(patchRe);
	if (patchMatch) paths.push(patchMatch[1]!);

	// tee file
	const teeRe = /\btee\s+(?:-[a-zA-Z]+\s+)*(\S+)/;
	const teeMatch = cmd.match(teeRe);
	if (teeMatch) paths.push(teeMatch[1]!);

	// Filter to things that look like file paths (have extension or / or .)
	return paths.filter((p) => {
		if (p.startsWith("-")) return false; // flags
		if (p.startsWith("(") || p.startsWith("{")) return false;
		return /\.\w+/.test(p) || p.includes("/") || p === p; // keep all for now
	});
}

/**
 * Walk a directory (shallow) and collect mtimes for trackable files.
 */
async function collectMtimes(
	dir: string,
	depth: number = 2,
): Promise<Map<string, number>> {
	const result = new Map<string, number>();

	async function walk(current: string, d: number): Promise<void> {
		if (d <= 0) return;
		let entries;
		try {
			entries = await readdir(current, { withFileTypes: true });
		} catch {
			return;
		}
		for (const entry of entries) {
			if (entry.name.startsWith(".") || entry.name === "node_modules") continue;
			const full = join(current, entry.name);
			if (entry.isDirectory()) {
				await walk(full, d - 1);
			} else if (entry.isFile()) {
				const ext = extname(entry.name).toLowerCase();
				if (TRACKABLE_EXTENSIONS.has(ext)) {
					try {
						const s = await stat(full);
						result.set(full, s.mtimeMs);
					} catch {
						// skip
					}
				}
			}
		}
	}

	await walk(dir, depth);
	return result;
}

// ---------------------------------------------------------------------------
// Interactive timeline component
// ---------------------------------------------------------------------------

interface TimelineEntry {
	entry: UndoEntry;
	isApplied: boolean;
	isCurrent: boolean;
}

type ThemeLike = {
	fg: (color: string, text: string) => string;
	bg: (color: string, text: string) => string;
	bold: (text: string) => string;
};

class TimelineComponent {
	private entries: TimelineEntry[];
	private cursorIdx: number;
	private scrollOffset: number;
	private onClose: (targetId: number | null) => void;
	private cwd: string;
	private theme: ThemeLike;
	private tui: TUI;
	private cachedRender: string[] | null = null;

	constructor(
		entries: TimelineEntry[],
		initialCursorIdx: number,
		cwd: string,
		theme: ThemeLike,
		tui: TUI,
		onClose: (targetId: number | null) => void,
	) {
		this.entries = entries;
		this.cursorIdx = initialCursorIdx;
		this.scrollOffset = Math.max(0, initialCursorIdx - 5);
		this.cwd = cwd;
		this.theme = theme;
		this.tui = tui;
		this.onClose = onClose;
	}

	private clampScroll(): void {
		const maxVisible = this.maxVisible();
		if (this.cursorIdx < this.scrollOffset) {
			this.scrollOffset = this.cursorIdx;
		}
		if (this.cursorIdx >= this.scrollOffset + maxVisible) {
			this.scrollOffset = this.cursorIdx - maxVisible + 1;
		}
	}

	private maxVisible(): number {
		// Reserve ~8 lines for header/footer chrome
		return Math.max(3, Math.min(this.tui.height - 8, 40));
	}

	handleInput(data: string): void {
		if (matchesKey(data, Key.up) || matchesKey(data, "k")) {
			if (this.cursorIdx > 0) this.cursorIdx--;
		} else if (matchesKey(data, Key.down) || matchesKey(data, "j")) {
			if (this.cursorIdx < this.entries.length - 1) this.cursorIdx++;
		} else if (matchesKey(data, Key.pageUp)) {
			this.cursorIdx = Math.max(0, this.cursorIdx - this.maxVisible());
		} else if (matchesKey(data, Key.pageDown)) {
			this.cursorIdx = Math.min(this.entries.length - 1, this.cursorIdx + this.maxVisible());
		} else if (matchesKey(data, Key.home)) {
			this.cursorIdx = 0;
		} else if (matchesKey(data, Key.end)) {
			this.cursorIdx = this.entries.length - 1;
		} else if (matchesKey(data, Key.enter) || matchesKey(data, Key.return)) {
			this.onClose(this.entries[this.cursorIdx]!.entry.id);
		} else if (matchesKey(data, Key.escape) || matchesKey(data, "ctrl+c")) {
			this.onClose(null);
		} else {
			return; // no state change, skip invalidate
		}

		this.clampScroll();
		this.cachedRender = null;
	}

	render(width: number): string[] {
		if (this.cachedRender) return this.cachedRender;

		const th = this.theme;
		const lines: string[] = [];

		// Header
		const headerText = th.fg("accent", th.bold(" File Change Timeline "));
		const border = th.fg("borderMuted", "─");
		const rule = border.repeat(3) + headerText + border.repeat(Math.max(0, width - 26));
		lines.push("");
		lines.push(truncateToWidth(rule, width));
		lines.push("");

		if (this.entries.length === 0) {
			lines.push(truncateToWidth(`  ${th.fg("dim", "No file changes recorded yet.")}`, width));
			lines.push("");
			lines.push(truncateToWidth(`  ${th.fg("dim", "Press Escape to close")}`, width));
			lines.push("");
			this.cachedRender = lines;
			return lines;
		}

		const maxVisible = this.maxVisible();
		const visibleEntries = this.entries.slice(
			this.scrollOffset,
			this.scrollOffset + maxVisible,
		);

		if (this.scrollOffset > 0) {
			lines.push(truncateToWidth(`  ${th.fg("dim", "  ↑ more above")}`, width));
		}

		for (let vi = 0; vi < visibleEntries.length; vi++) {
			const idx = this.scrollOffset + vi;
			const { entry, isApplied, isCurrent } = visibleEntries[vi]!;
			const isCursor = idx === this.cursorIdx;

			const files = entry.snapshots
				.map((s) => {
					const p = shortPath(s.path, this.cwd);
					if (s.before === null) return p + th.fg("success", "+");
					if (s.after === null) return p + th.fg("error", "x");
					return p;
				})
				.join(" ");
			const time = new Date(entry.timestamp).toLocaleTimeString();

			let rail: string;
			if (isCurrent) {
				rail = th.fg("accent", "◀");
			} else if (isApplied) {
				rail = th.fg("success", "│");
			} else {
				rail = th.fg("dim", "╎");
			}

			let node: string;
			if (isCurrent) {
				node = th.fg("accent", th.bold("●"));
			} else if (isApplied) {
				node = th.fg("success", "●");
			} else {
				node = th.fg("dim", "○");
			}

			const tool = th.fg("toolTitle", entry.tool);
			const timeStr = th.fg("dim", time);

			let line: string;
			if (isCursor) {
				line = th.bg("selectedBg", ` ${rail} ${node} #${entry.id} ${tool} ${files} ${timeStr} `);
			} else {
				line = ` ${rail} ${node} ${th.fg("muted", `#${entry.id}`)} ${tool} ${th.fg("muted", files)} ${timeStr}`;
			}

			lines.push(truncateToWidth(line, width));
		}

		if (this.scrollOffset + maxVisible < this.entries.length) {
			lines.push(truncateToWidth(`  ${th.fg("dim", "  ↓ more below")}`, width));
		}

		const currentPos = this.entries[this.cursorIdx]!;
		const posLabel = currentPos.isApplied
			? th.fg("success", "applied")
			: th.fg("dim", "undone");
		lines.push("");
		lines.push(
			truncateToWidth(
				`  ${th.fg("muted", "Position:")} ${posLabel}  ${th.fg("dim", `#${currentPos.entry.id} / #${this.entries[this.entries.length - 1]!.entry.id}`)}`,
				width,
			),
		);

		lines.push("");
		lines.push(
			truncateToWidth(
				`  ${th.fg("dim", "↑↓ navigate")}  ${th.fg("dim", "Enter jump")}  ${th.fg("dim", "Esc cancel")}`,
				width,
			),
		);
		lines.push("");

		this.cachedRender = lines;
		return lines;
	}

	invalidate(): void {
		this.cachedRender = null;
	}
}

// ---------------------------------------------------------------------------
// Extension
// ---------------------------------------------------------------------------

export default function (pi: ExtensionAPI) {
	let cwd = "";
	let store: UndoStore | null = null;

	// Per-toolCallId pending state (fix #3 — parallel-safe)
	const pending: Map<string, PendingCall> = new Map();
	let position = 0;

	// ------- Open / close -------

	function openStore(ctxCwd: string): void {
		cwd = ctxCwd;
		const dbPath = join(ctxCwd, ".pi", "undo-history.db");
		store = new UndoStore(dbPath);
		position = store.getPosition();
	}

	function closeStore(): void {
		if (store) {
			store.close();
			store = null;
		}
	}

	function persistPosition(): void {
		if (store) store.setPosition(position);
	}

	// ------- Jump to a target entry id -------

	async function jumpTo(targetId: number): Promise<string | null> {
		if (!store) return null;
		if (targetId === position) return null;

		let entries: UndoEntry[];

		if (targetId < position) {
			entries = store.getEntriesRange(targetId, position);
			for (let i = entries.length - 1; i >= 0; i--) {
				for (const snap of entries[i].snapshots) {
					await writeFileFromSnapshot(snap.path, snap.before);
				}
			}
		} else {
			entries = store.getEntriesRange(position, targetId);
			for (const entry of entries) {
				for (const snap of entry.snapshots) {
					await writeFileFromSnapshot(snap.path, snap.after);
				}
			}
		}

		position = targetId;
		persistPosition();

		return formatEntriesSummary(entries);
	}

	function formatEntriesSummary(entries: UndoEntry[]): string {
		return entries
			.map((e) => {
				const files = e.snapshots.map((s) => shortPath(s.path, cwd)).join(", ");
				return `  - ${e.tool}: ${files}`;
			})
			.join("\n");
	}

	// ------- Notify model about file state changes -------

	function notifyModel(summary: string, entryCount: number, direction: "undone" | "redone"): void {
		pi.sendMessage(
			{
				customType: "undo-redo",
				content: `${entryCount} file change(s) ${direction}:\n${summary}`,
				display: true,
				details: { action: direction, changes: summary },
			},
			{ deliverAs: "nextTurn" },
		);
	}

	// ------- Record a completed tool call -------

	async function recordEntry(
		toolCallId: string,
		tool: string,
		description: string,
		beforeSnapshots: Map<string, string | null>,
	): Promise<void> {
		if (!store) return;

		const snapshots: FileSnapshot[] = [];
		for (const [ap, before] of beforeSnapshots) {
			const after = await readFileOrNull(ap);
			if (before !== after) {
				snapshots.push({ path: ap, before, after });
			}
		}

		if (snapshots.length > 0) {
			// Truncate redo history
			if (position < store.getPosition()) {
				store.deleteAfter(position);
			}

			const entryId = store.addEntry(tool, description, snapshots);
			position = entryId;
			persistPosition();
			store.pruneIfNeeded();
		}
	}

	// ------- Capture before-state on tool_call -------

	pi.on("tool_call", async (event, ctx) => {
		const tool = event.toolName;
		const toolCallId = event.toolCallId;

		if (tool === "write") {
			const input = event.input as { path?: string; content?: string };
			if (!input.path) return;
			const ap = resolveAbs(ctx.cwd, input.path);
			const before = await readFileOrNull(ap);
			const beforeSnapshots = new Map<string, string | null>();
			beforeSnapshots.set(ap, before);
			pending.set(toolCallId, { tool: "write", description: input.path, beforeSnapshots });
		}

		if (tool === "edit") {
			const input = event.input as {
				path?: string;
				edits?: Array<{ oldText: string; newText: string }>;
			};
			if (!input.path) return;
			const ap = resolveAbs(ctx.cwd, input.path);
			const before = await readFileOrNull(ap);
			const beforeSnapshots = new Map<string, string | null>();
			beforeSnapshots.set(ap, before);
			pending.set(toolCallId, { tool: "edit", description: input.path, beforeSnapshots });
		}

		if (tool === "bash") {
			const input = event.input as { command?: string };
			if (!input.command) return;
			const cmd = input.command.trim();

			const mutatingPatterns =
				/\b(sed|awk|perl|python|node|ruby)\b.*(-i|--in-place)\b|\btee\b|\bdd\b|\b>[>=]?\s*\S|\b>>\s*\S|\bmv\b|\bcp\b|\btruncate\b|\binstall\b|\bpatch\b/i;
			if (!mutatingPatterns.test(cmd)) return;

			const desc = cmd.length > 120 ? cmd.slice(0, 120) + "..." : cmd;

			// Snapshot files that the command references directly
			const referencedPaths = extractPathsFromCommand(cmd);
			const beforeSnapshots = new Map<string, string | null>();
			for (const relPath of referencedPaths) {
				const ap = resolveAbs(ctx.cwd, relPath);
				const content = await readFileOrNull(ap);
				if (content !== null) {
					beforeSnapshots.set(ap, content);
				}
			}

			// Also collect mtimes of trackable files in the project for diff detection
			const mtimes = await collectMtimes(ctx.cwd);

			pending.set(toolCallId, {
				tool: "bash",
				description: desc,
				beforeSnapshots,
				mtimes,
			});
		}
	});

	// ------- Capture after-state on tool_result -------

	pi.on("tool_result", async (event, ctx) => {
		const tool = event.toolName;
		const toolCallId = event.toolCallId;

		if (tool !== "write" && tool !== "edit" && tool !== "bash") return;

		const call = pending.get(toolCallId);
		if (!call) return;
		pending.delete(toolCallId);

		if (event.isError) return;
		if (!store) return;

		if (call.tool === "bash") {
			// For bash: check which files actually changed via mtime diff
			const bashCall = call as PendingCall & { mtimes?: Map<string, number> };
			const beforeMtimes = bashCall.mtimes;
			if (beforeMtimes) {
				const afterMtimes = await collectMtimes(ctx.cwd);
				for (const [path, afterMtime] of afterMtimes) {
					const beforeMtime = beforeMtimes.get(path);
					if (beforeMtime === undefined || beforeMtime !== afterMtime) {
						// File changed or is new
						if (!bashCall.beforeSnapshots.has(path)) {
							// We didn't snapshot this file before — we lost the before content.
							// Read current content as "after", mark before as unknown.
							// We can still track it for future undo from this point.
							const after = await readFileOrNull(path);
							bashCall.beforeSnapshots.set(path, null);
							// Note: before=null normally means "file didn't exist", but here
							// it means "we don't know what it was before". The undo will
							// delete the file which is wrong. Skip these entries.
						}
					}
				}
			}

			// Only record if we actually had before-content for changed files
			if (bashCall.beforeSnapshots.size > 0) {
				await recordEntry(toolCallId, call.tool, call.description, call.beforeSnapshots);
			}
			return;
		}

		// write or edit
		await recordEntry(toolCallId, call.tool, call.description, call.beforeSnapshots);
	});

	// ------- Session lifecycle -------

	pi.on("session_start", async (_event, ctx) => {
		closeStore();
		openStore(ctx.cwd);
	});

	pi.on("session_shutdown", async () => {
		closeStore();
	});

	// ------- /undo -------

	pi.registerCommand("undo", {
		description: "Undo the last file change(s). Usage: /undo [n]",
		handler: async (args, ctx) => {
			if (!store) return;

			const count = Math.max(1, parseInt(args?.trim() || "1", 10) || 1);
			const targetId = Math.max(0, position - count);

			if (targetId === position) {
				ctx.ui.notify("Nothing to undo", "warning");
				return;
			}

			const summary = await jumpTo(targetId);
			if (summary) {
				ctx.ui.notify(`Undid change(s):\n${summary}`, "info");
				notifyModel(summary, position - targetId, "undone");
			}
		},
	});

	// ------- /redo -------

	pi.registerCommand("redo", {
		description: "Redo the last undone file change(s). Usage: /redo [n]",
		handler: async (args, ctx) => {
			if (!store) return;

			const count = Math.max(1, parseInt(args?.trim() || "1", 10) || 1);
			const undoneIds = store.getEntryIdsAfter(position);
			if (undoneIds.length === 0) {
				ctx.ui.notify("Nothing to redo", "warning");
				return;
			}

			const targetId = undoneIds[Math.min(count, undoneIds.length) - 1]!;
			const summary = await jumpTo(targetId);
			if (summary) {
				ctx.ui.notify(`Redid change(s):\n${summary}`, "info");
				notifyModel(summary, targetId - position, "redone");
			}
		},
	});

	// ------- /undo-log (interactive timeline) -------

	pi.registerCommand("undo-log", {
		description: "Interactive file change timeline. Navigate with arrows, Enter to jump.",
		handler: async (_args, ctx) => {
			if (!store) return;

			const entries = store.getAllEntries();

			if (entries.length === 0) {
				ctx.ui.notify("No file changes recorded yet.", "info");
				return;
			}

			if (!ctx.hasUI) {
				const lines = entries.map((e) => {
					const marker = e.id <= position ? "done" : "undone";
					const files = e.snapshots.map((s) => shortPath(s.path, cwd)).join(", ");
					return `[${marker}] #${e.id} ${e.tool} ${files}`;
				});
				ctx.ui.notify(lines.join("\n"), "info");
				return;
			}

			const timeline: TimelineEntry[] = entries.map((e) => ({
				entry: e,
				isApplied: e.id <= position,
				isCurrent: e.id === position,
			}));

			const cursorStart = timeline.findIndex((t) => t.isCurrent);
			const initialCursor = cursorStart >= 0 ? cursorStart : timeline.length - 1;

			const targetId = await ctx.ui.custom<number | null>((tui, theme, _kb, done) => {
				return new TimelineComponent(timeline, initialCursor, cwd, theme, tui, done);
			});

			if (targetId === null || targetId === position) return;

			const direction = targetId < position ? "undone" : "redone";
			const summary = await jumpTo(targetId);
			if (summary) {
				const verb = direction === "undone" ? "Undid" : "Redid";
				ctx.ui.notify(`${verb} change(s):\n${summary}`, "info");
				notifyModel(summary, Math.abs(targetId - position), direction);
			}
		},
	});
}

