const fs = require('fs');
const ts = require('typescript');

const src = fs.readFileSync('.pi/extensions/undo-redo.ts', 'utf-8');
const result = ts.transpileModule(src, {
  compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022, esModuleInterop: true },
});

const tmp = '/tmp/test-undo-e2e.js';
fs.writeFileSync(tmp, result.outputText);
const mod = require(tmp);

(async () => {
  const dbPath = '/tmp/test-undo-history.db';
  try { fs.unlinkSync(dbPath); } catch {}

  let sessionStartHandler, shutdownHandler, toolCallHandler, toolResultHandler;
  const handlers = { undo: {}, redo: {}, log: {} };
  const sentMessages = [];

  const mockPi = {
    on(event, handler) {
      if (event === 'session_start') sessionStartHandler = handler;
      if (event === 'session_shutdown') shutdownHandler = handler;
      if (event === 'tool_call') toolCallHandler = handler;
      if (event === 'tool_result') toolResultHandler = handler;
    },
    registerCommand(name, opts) {
      if (name === 'undo') Object.assign(handlers.undo, opts);
      if (name === 'redo') Object.assign(handlers.redo, opts);
      if (name === 'undo-log') Object.assign(handlers.log, opts);
    },
    sendMessage(msg, opts) {
      sentMessages.push({ msg, opts });
    },
  };
  mod.default(mockPi);

  const cwd = '/tmp/test-undo-project';
  fs.mkdirSync(cwd + '/.pi', { recursive: true });

  const mockCtx = {
    cwd,
    hasUI: false,
    ui: { notify: (msg, type) => console.log('[' + type + ']', msg) },
  };

  await sessionStartHandler({ reason: 'startup' }, mockCtx);

  // Write change 1
  fs.writeFileSync(cwd + '/hello.txt', 'original');
  await toolCallHandler({ toolName: 'write', toolCallId: 'tc1', input: { path: 'hello.txt', content: 'v1' } }, mockCtx);
  fs.writeFileSync(cwd + '/hello.txt', 'v1');
  await toolResultHandler({ toolName: 'write', toolCallId: 'tc1', isError: false }, mockCtx);
  console.log('1:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // Write change 2
  await toolCallHandler({ toolName: 'write', toolCallId: 'tc2', input: { path: 'hello.txt', content: 'v2' } }, mockCtx);
  fs.writeFileSync(cwd + '/hello.txt', 'v2');
  await toolResultHandler({ toolName: 'write', toolCallId: 'tc2', isError: false }, mockCtx);
  console.log('2:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // Write change 3
  await toolCallHandler({ toolName: 'write', toolCallId: 'tc3', input: { path: 'hello.txt', content: 'v3' } }, mockCtx);
  fs.writeFileSync(cwd + '/hello.txt', 'v3');
  await toolResultHandler({ toolName: 'write', toolCallId: 'tc3', isError: false }, mockCtx);
  console.log('3:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // Undo to v2
  await handlers.undo.handler('', mockCtx);
  console.log('undo 1:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // Undo to v1
  await handlers.undo.handler('', mockCtx);
  console.log('undo 2:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // Redo to v2
  await handlers.redo.handler('', mockCtx);
  console.log('redo:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // New write (should truncate redo history)
  await toolCallHandler({ toolName: 'write', toolCallId: 'tc4', input: { path: 'hello.txt', content: 'v2b' } }, mockCtx);
  fs.writeFileSync(cwd + '/hello.txt', 'v2b');
  await toolResultHandler({ toolName: 'write', toolCallId: 'tc4', isError: false }, mockCtx);
  console.log('new write:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // Redo should be empty
  await handlers.redo.handler('', mockCtx);

  // Undo 1
  await handlers.undo.handler('', mockCtx);
  console.log('undo after branch:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // Error case: tool fails - state should not change
  await toolCallHandler({ toolName: 'write', toolCallId: 'tc5', input: { path: 'hello.txt', content: 'should not persist' } }, mockCtx);
  await toolResultHandler({ toolName: 'write', toolCallId: 'tc5', isError: true }, mockCtx);
  console.log('after failed write:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // New file creation then undo (file should be deleted)
  await toolCallHandler({ toolName: 'write', toolCallId: 'tc6', input: { path: 'brand-new.txt', content: 'new file' } }, mockCtx);
  fs.writeFileSync(cwd + '/brand-new.txt', 'new file');
  await toolResultHandler({ toolName: 'write', toolCallId: 'tc6', isError: false }, mockCtx);
  console.log('brand new exists:', fs.existsSync(cwd + '/brand-new.txt'));

  await handlers.undo.handler('', mockCtx);
  console.log('after undo create, exists:', fs.existsSync(cwd + '/brand-new.txt'));

  // Position persistence test: simulate crash by closing and reopening
  await shutdownHandler({ reason: 'quit' }, mockCtx);
  await sessionStartHandler({ reason: 'startup' }, mockCtx);

  // Position should have survived (we were at tc4)
  await handlers.redo.handler('', mockCtx);
  console.log('after crash-recovery redo:', fs.readFileSync(cwd + '/hello.txt', 'utf-8'));

  // Notify model test
  console.log('messages sent:', sentMessages.length);
  console.log('sample message:', sentMessages[sentMessages.length - 1]?.msg?.content);

  await shutdownHandler({ reason: 'quit' }, mockCtx);
  try { fs.unlinkSync(dbPath); } catch {}

  console.log('\\nAll e2e tests passed!');
})();
