function simpleLineDiff(oldStr: string, newStr: string): { added: number; removed: number } {
  const oldLines = oldStr.split("\n");
  const newLines = newStr.split("\n");

  // LCS DP
  const m = oldLines.length;
  const n = newLines.length;

  // For small files this is fine. For very large files, cap it.
  if (m * n > 1_000_000) {
    // Fallback to simple line count
    return { added: Math.max(0, n - m), removed: Math.max(0, m - n) };
  }

  const dp: number[][] = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (oldLines[i-1] === newLines[j-1]) {
        dp[i][j] = dp[i-1][j-1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]);
      }
    }
  }

  const lcs = dp[m][n];
  return { added: n - lcs, removed: m - lcs };
}

