	// Find next change
	while (i < edit.length && edit[i]!.type === " ") i++;
	if (i >= edit.length) break;

	// Determine hunk bounds (3 context before, change, 3 context after)
	const changeStart = Math.max(0, i - 3);
	// Find end of change block
	let changeEnd = i;
	while (changeEnd < edit.length && edit[changeEnd]!.type !== " ") changeEnd++;
