	const beforeLines = edit.slice(changeStart, hunkEnd).filter((e) => e.type === " " || e.type === "-");
	const afterLines = edit.slice(changeStart, hunkEnd).filter((e) => e.type === " " || e.type === "+");

	output.push(`@@ -${beforeLines.length > 0 ? `1,${beforeLines.length}` : "0,0"} +${afterLines.length > 0 ? `1,${afterLines.length}` : "0,0"} @@`);

	for (let k = changeStart; k < hunkEnd; k++) {
		const e = edit[k]!;
		output.push(`${e.type}${e.line}`);
	}

	i = changeEnd;
}

