cd /home/quiet/Workspace/pi && for f in .pi/extensions/*.ts; do
  echo -n "Checking $f... "
  node -e "
    const ts = require('typescript');
    const fs = require('fs');
    const src = fs.readFileSync('$f', 'utf-8');
    const result = ts.transpileModule(src, {
      compilerOptions: { module: ts.ModuleKind.ES2022, target: ts.ScriptTarget.ES2022, esModuleInterop: true },
      reportDiagnostics: true,
    });
    if (result.diagnostics?.length) {
      result.diagnostics.forEach(d => console.error(ts.flattenDiagnosticMessageText(d.messageText, '\n')));
      process.exit(1);
    }
    console.log('OK');
  " 2>&1
done

